// @generated by:gauntlet run:anatoly-orion-recon
#[allow(dead_code)]
mod common;

use anatoly::{scan::scan_configured, scan_options::ScanOptions};
use common::{Server, limits, response};
use serde_json::Value;
use std::process::{Command, Output};

const ORION: &str = include_str!("fixtures/orion-minimal.html");

fn options() -> ScanOptions {
    let mut options = ScanOptions {
        samples: 1,
        discover: false,
        ..ScanOptions::default()
    };
    options.network.no_proxy = true;
    options
}

fn observe(headers: &str, body: &str, options: ScanOptions) -> Value {
    let headers = headers.to_owned();
    let body = body.to_owned();
    let server = Server::new(move |_| response("200 OK", &headers, &body));
    serde_json::to_value(scan_configured(&server.url, limits(), &options).unwrap()).unwrap()
}

fn technology<'a>(report: &'a Value, name: &str) -> &'a Value {
    report["technologies"]
        .as_array()
        .expect("technology observations must be serialized")
        .iter()
        .find(|technology| technology["name"] == name)
        .unwrap_or_else(|| panic!("missing {name} in {report}"))
}

fn assert_unknown_php(report: &Value) {
    assert!(report["version"].is_null(), "{report}");
    assert_eq!(report["version_status"], "unknown");
    assert!(report["version_candidates"].as_array().unwrap().is_empty());
    assert_eq!(report["analysis"]["detection_level"], "unknown");
    assert_eq!(report["verdict"], "inconclusive");
}

fn cli(server: &Server, mode: &str, flags: &[&str]) -> Output {
    Command::new(env!("CARGO_BIN_EXE_anatoly"))
        .args([
            mode,
            &server.url,
            "--samples",
            "1",
            "--delay-ms",
            "0",
            "--no-proxy",
            "--no-banner",
            "--color",
            "never",
        ])
        .args(flags)
        .output()
        .unwrap()
}

#[test]
fn t_ac_01_craft_header_aliases_are_normalized_without_assigning_a_php_version() {
    for declaration in ["Craft CMS", "CraftCMS", "craft cms", "CRAFTCMS"] {
        let report = observe(
            &format!("x-PoWeReD-bY: {declaration}\r\nServer: nginx/1.18.0\r\n"),
            "<p>Welcome</p>",
            options(),
        );

        let craft = technology(&report, "Craft CMS");
        assert!(craft["versions"].as_array().unwrap().is_empty());
        let observations = craft["observations"].as_array().unwrap();
        assert!(!observations.is_empty());
        assert!(observations.iter().all(|o| {
            o["http_status"] == 200
                && !o["source"].as_str().unwrap().is_empty()
                && !o["method"].as_str().unwrap().is_empty()
                && !o["detail"].as_str().unwrap().is_empty()
        }));
        assert_eq!(report["runtime"]["status"], "inferred");
        assert_unknown_php(&report);
    }
}

#[test]
fn t_ac_02_visible_craft_attribution_handles_inline_markup_entities_and_whitespace() {
    for body in [
        "<p>Powered by CraftCMS</p>",
        "<footer>Powered\n by\t Craft CMS</footer>",
        "<footer><p>Powered <span>by</span> <a href='https://craftcms.com'>CraftCMS</a></p></footer>",
        "<p>Powered&nbsp;by <strong>Craft&#67;MS</strong></p>",
    ] {
        let report = observe("", body, options());

        technology(&report, "Craft CMS");
        assert_eq!(report["runtime"]["status"], "inferred", "{body}");
        assert_unknown_php(&report);
    }
}

#[test]
fn t_ac_03_generator_metadata_is_parsed_by_actual_attribute_name_and_value() {
    for body in [
        "<meta name='generator' content='Craft CMS 5.8.1'>",
        "<META CONTENT='CraftCMS 5.8.1' NAME=GENERATOR>",
        "<meta content='Craft CMS 5.8.1'\nname = generator>",
    ] {
        let report = observe("", body, options());

        let craft = technology(&report, "Craft CMS");
        assert!(
            craft["versions"]
                .as_array()
                .unwrap()
                .contains(&Value::from("5.8.1"))
        );
        assert_unknown_php(&report);
    }
}

#[test]
fn t_ac_04_documentation_comments_and_inert_markup_do_not_become_technology_observations() {
    for body in [
        "<article>This article compares Craft CMS, WordPress and Laravel.</article>",
        "<article><p>The phrase Powered by CraftCMS appears in the documentation.</p></article>",
        "<!-- <meta name='generator' content='Craft CMS 5.8.1'><p>Powered by CraftCMS</p> -->",
        "<script>const sample = '<meta name=generator content=CraftCMS>'; const footer = 'Powered by CraftCMS';</script>",
        "<style>p:before { content: 'Powered by CraftCMS'; }</style>",
        "<template><meta name='generator' content='CraftCMS'><p>Powered by CraftCMS</p></template>",
        "<pre><code>Powered by CraftCMS</code></pre>",
        "<meta name='description' data-generator='Craft CMS' content='A tutorial'>",
        "<meta name='not-generator' content='Craft CMS'>",
        "<p>CraftCMS is mentioned in an ordinary sentence.</p>",
    ] {
        let report = observe("", body, options());

        assert!(
            report["technologies"].as_array().unwrap().is_empty(),
            "{body}: {report}"
        );
        assert_eq!(report["runtime"]["status"], "unknown", "{body}");
        assert_unknown_php(&report);
    }
}

#[test]
fn t_ac_05_multiple_channels_and_repeated_samples_preserve_unique_provenance() {
    let mut scan_options = options();
    scan_options.samples = 3;

    let report = observe("X-Powered-By: Craft CMS\r\n", ORION, scan_options);

    let technologies = report["technologies"].as_array().unwrap();
    assert_eq!(
        technologies
            .iter()
            .filter(|t| t["name"] == "Craft CMS")
            .count(),
        1
    );
    let observations = technology(&report, "Craft CMS")["observations"]
        .as_array()
        .unwrap();
    assert!(
        observations.len() >= 2,
        "header and attribution must both survive"
    );
    for (index, observation) in observations.iter().enumerate() {
        assert!(
            !observations[..index].contains(observation),
            "duplicate {observation}"
        );
    }
    assert!(
        report["signals"]
            .as_array()
            .unwrap()
            .iter()
            .any(|s| s["category"] == "application")
    );
    assert_eq!(report["requests_sent"], 3);
    assert_unknown_php(&report);
}

