#[test]
fn t_ac_08_disabling_cookie_hints_suppresses_cookie_based_application_identification() {
    let headers = "Set-Cookie: laravel_session=SYNTHETIC_SESSION_VALUE; HttpOnly\r\n";
    let normal = observe(headers, "<p>Welcome</p>", options());
    technology(&normal, "Laravel");
    assert_eq!(normal["runtime"]["status"], "inferred");

    let mut scan_options = options();
    scan_options.no_cookie_hints = true;
    let disabled = observe(headers, "<p>Welcome</p>", scan_options);

    assert!(disabled["technologies"].as_array().unwrap().is_empty());
    assert_eq!(disabled["runtime"]["status"], "unknown");
    assert!(!disabled.to_string().contains("SYNTHETIC_SESSION_VALUE"));
}

