#[test]
fn t_ac_10_orion_technologies_reach_cli_json_and_terminal_without_changing_the_cve_verdict() {
    let server = Server::new(|_| response("200 OK", "X-Powered-By: Craft CMS\r\n", ORION));

    let machine = cli(&server, "scan", &["--no-discover", "--json"]);
    assert_eq!(machine.status.code(), Some(2));
    let json: Value = serde_json::from_slice(&machine.stdout).unwrap();
    let report = &json["targets"][0];
    technology(report, "Craft CMS");
    assert_unknown_php(report);

    let human = cli(&server, "scan", &["--no-discover"]);
    let terminal = String::from_utf8(human.stdout).unwrap();
    assert_eq!(human.status.code(), Some(2));
    assert!(terminal.contains("Craft CMS"), "{terminal}");
    assert!(
        terminal.to_ascii_lowercase().contains("inferred"),
        "{terminal}"
    );
    assert!(
        terminal.to_ascii_lowercase().contains("inconclusive"),
        "{terminal}"
    );
}

#[test]
fn t_ac_10_exposure_preserves_technology_observations_and_php_uncertainty() {
    let server = Server::new(|path| {
        if path == "/" {
            response("200 OK", "X-Powered-By: Craft CMS\r\n", ORION)
        } else {
            response("404 Not Found", "", "Not found")
        }
    });

    let output = cli(&server, "exposure", &["--max-requests", "32", "--json"]);

    assert_eq!(output.status.code(), Some(2));
    let json: Value = serde_json::from_slice(&output.stdout).unwrap();
    technology(&json["targets"][0], "Craft CMS");
    assert_unknown_php(&json["targets"][0]);
}
